  3→/**
  4→ * Tool approval card shown when Claude requests permission to run a tool.
  5→ *
  6→ * Displays the tool name, optional description, and formatted input params
  7→ * with Allow / Deny buttons. Once the user responds, buttons are replaced
  8→ * with a status badge. Rendered in place of a regular {@link Message} when
  9→ * the message carries a `controlRequest` payload.
 10→ */
 11→
 12→import { ShieldAlert, Check, X } from "lucide-react";
 13→import { useState } from "react";
 14→import { Button } from "@/components/ui/button";
 15→import type { ChatMessage } from "@/lib/types";
