  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`.
 37→ * 4. Server immediately sends the pending prompt as a `user` message.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * Note: CLI 2.1.41 sent `hook_started`/`hook_response` before `init`; CLI 2.1.42+
 44→ * waits for the server to send the first user message. The `hook_response` handler
 45→ * is kept as a fallback for older CLI versions.
 46→ *
 47→ * ## Resilience features
 48→ *
 49→ * - **Server-side message history** — every relay message is stored per-agent.
 50→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 51→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 52→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 53→ *   can reconnect to the new server if they retry their WebSocket connection.
 54→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 55→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 56→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 57→ */
 58→import { WebSocketServer, WebSocket } from "ws";
 59→import { execSync, spawn } from "child_process";
 60→import { randomBytes } from "crypto";
 61→import type { IncomingMessage } from "http";
 62→import type {
 63→  BrowserMessage,
 64→  ClaudeMessage,
 65→  ServerMessage,
 66→  AgentStatus,
 67→  AgentInfo,
 68→  Task,
 69→} from "../lib/types";
 70→import { SessionStore, type PersistedAgent } from "./session-store";
 71→import { TaskStore } from "./task-store";
 72→
 73→const PORT = 9900;
 74→const TMUX_SESSION_PREFIX = "thos-agent";
 75→
 76→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 77→function isAllowedIP(ip: string | undefined): boolean {
 78→  if (!ip) return false;
 79→  // Strip IPv6-mapped IPv4 prefix
 80→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 81→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 82→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 83→  const parts = addr.split(".");
 84→  if (parts.length !== 4) return false;
 85→  const first = parseInt(parts[0], 10);
 86→  const second = parseInt(parts[1], 10);
 87→  return first === 100 && second >= 64 && second <= 127;
 88→}
 89→
 90→const wss = new WebSocketServer({
 91→  port: PORT,
 92→  verifyClient: (info) => {
 93→    const ip = info.req.socket.remoteAddress;
 94→    const allowed = isAllowedIP(ip);
 95→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 96→    return allowed;
 97→  },
 98→});
 99→const store = new SessionStore();
100→
101→// ── Multi-agent state ──────────────────────────────────────────────────────
102→
103→interface AgentState {
104→  agentId: string;
105→  claudeSocket: WebSocket | null;
106→  tmuxSession: string | null;
107→  pendingPrompt: string | null;
108→  status: AgentStatus;
109→  label: string;
110→  createdAt: number;
111→  /** Captured from system/init, used in subsequent user messages. */
112→  sessionId: string | null;
113→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
114→  pendingControlRequests: Map<string, Record<string, unknown>>;
115→  /** All messages sent to the browser for this agent (source of truth). */
116→  messageHistory: ServerMessage[];
117→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
118→  pendingMessages: string[];
119→}
120→
121→const agents = new Map<string, AgentState>();
122→const taskStore = new TaskStore();
123→const tasks = new Map<string, Task>();
124→
125→/** All active browser connections (supports multiple tabs). */
126→const browserSockets = new Set<WebSocket>();
127→
128→/** Generate a short random agent ID. */
129→function newAgentId(): string {
130→  return randomBytes(4).toString("hex");
131→}
132→
133→// ── tmux helpers ───────────────────────────────────────────────────────────
134→
135→/** Return the set of currently alive tmux session names matching the thos prefix. */
136→function listAliveTmuxSessions(): Set<string> {
137→  try {
138→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
139→      encoding: "utf-8",
140→    }).trim();
141→    if (!output) return new Set();
142→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
143→  } catch {
144→    return new Set();
145→  }
146→}
147→
148→// ── Persistence helpers ────────────────────────────────────────────────────
149→
150→/** Build a PersistedAgent snapshot from live state. */
151→function toPersistedAgent(agent: AgentState): PersistedAgent {
152→  return {
153→    id: agent.agentId,
154→    state: {
155→      agentId: agent.agentId,
156→      status: agent.status,
157→      tmuxSession: agent.tmuxSession,
158→      label: agent.label,
159→      createdAt: agent.createdAt,
160→      sessionId: agent.sessionId,
161→    },
162→    messageHistory: agent.messageHistory,
163→  };
164→}
165→
166→/**
167→ * Compact a message history by deduplicating cumulative snapshots.
168→ * Keeps only the last version of each assistant/user message ID.
169→ * Called on restore to shrink legacy bloated histories.
170→ */
171→function compactHistory(history: ServerMessage[]): ServerMessage[] {
172→  // Build a map of msgId → last index
173→  const lastIndex = new Map<string, number>();
174→  for (let i = 0; i < history.length; i++) {
175→    const id = getRelayMessageId(history[i]);
176→    if (id) lastIndex.set(id, i);
177→  }
178→  // Keep only messages that are either non-deduplicable or the last occurrence
179→  return history.filter((msg, i) => {
180→    const id = getRelayMessageId(msg);
181→    if (!id) return true; // non-relay or no message ID — always keep
182→    return lastIndex.get(id) === i;
183→  });
184→}
185→
186→/** Persist agent state (debounced — use for streaming events). */
187→function persistAgent(agent: AgentState) {
188→  store.save(toPersistedAgent(agent));
189→}
190→
191→/** Persist agent state immediately (use for critical state changes). */
192→function persistAgentSync(agent: AgentState) {
193→  store.saveSync(toPersistedAgent(agent));
194→}
195→
196→// ── Restore from disk on startup ───────────────────────────────────────────
197→
198→function restoreAgents() {
199→  const persisted = store.loadAll();
200→  const aliveSessions = listAliveTmuxSessions();
201→
202→  for (const p of persisted) {
203→    const agent: AgentState = {
204→      agentId: p.state.agentId,
205→      claudeSocket: null,
206→      tmuxSession: p.state.tmuxSession,
207→      pendingPrompt: null,
208→      status: p.state.status,
209→      label: p.state.label,
210→      createdAt: p.state.createdAt,
211→      sessionId: p.state.sessionId,
212→      pendingControlRequests: new Map(),
213→      messageHistory: compactHistory(p.messageHistory),
214→      pendingMessages: [],
215→    };
216→
217→    // Determine status for agents that were active when the server last ran
218→    if (agent.status !== "done" && agent.status !== "error") {
219→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
220→      if (tmuxAlive) {
221→        // tmux session still alive — CLI may reconnect to this server
222→        agent.status = "disconnected";
223→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
224→      } else {
225→        // tmux session gone — agent is archived
226→        agent.status = "done";
227→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
228→      }
229→    }
230→
231→    agents.set(agent.agentId, agent);
232→    const originalCount = p.messageHistory.length;
233→    const compactedCount = agent.messageHistory.length;
234→    const saved = originalCount - compactedCount;
235→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
236→
237→    // Persist compacted history back to disk
238→    if (saved > 0) {
239→      persistAgentSync(agent);
240→    }
241→  }
242→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
243→}
244→
245→restoreAgents();
