  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. No agent is auto-selected — the user stays on the new-agent
 18→ *    creation screen until they explicitly pick or spawn an agent.
 19→ *
 20→ * ## Lazy history loading
 21→ *
 22→ * Message histories are loaded on demand. When `activeAgentId` changes
 23→ * and the agent hasn't been loaded yet, the hook sends
 24→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 25→ * When the server responds with `message_history`, the agent's messages
 26→ * are populated and `historyLoading` becomes false.
 27→ *
 28→ * The `loadedAgents` Set tracks which agents have been fetched so that
 29→ * switching back to a previously viewed agent is instant.
 30→ *
 31→ * ## Resilience features
 32→ *
 33→ * - Handles `message_history` replay from server on demand.
 34→ * - Handles `cli_disconnected` / `cli_connected` events.
 35→ * - Deduplicates messages using a per-agent processed count.
 36→ * - Robust reconnection guard (clears previous timer before scheduling).
 37→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 38→ *
 39→ * ## Logging
 40→ *
 41→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 42→ * in the browser console to debug connection and message delivery issues.
 43→ */
 44→
 45→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 46→import type {
 47→  AgentInfo,
 48→  AgentStatus,
 49→  ChatMessage,
 50→  ClaudeAssistant,
 51→  ClaudeControlRequest,
 52→  ClaudeMessage,
 53→  ClaudeResult,
 54→  ClaudeSystemInit,
 55→  ServerMessage,
 56→  ServerMessageHistory,
 57→  ServerTaskList,
 58→  ServerTaskUpdated,
 59→  ServerTaskDeleted,
 60→  Task,
 61→  TaskPriority,
 62→  ToolCallInfo,
 63→  UserQuestion,
 64→} from "@/lib/types";
 65→
 66→/** Connect to the WS server on the same host the page was loaded from. */
 67→const WS_URL =
 68→  typeof window !== "undefined"
 69→    ? `ws://${window.location.hostname}:9900/browser`
 70→    : "ws://localhost:9900/browser";
 71→
 72→/** Per-agent client state. */
 73→export interface AgentClientState {
 74→  status: AgentStatus;
 75→  messages: ChatMessage[];
 76→  /** Raw Claude NDJSON messages for debug view. */
 77→  rawMessages: ClaudeMessage[];
 78→  label: string;
 79→  tmuxSession: string | null;
 80→  createdAt: number;
 81→}
 82→
 83→/**
 84→ * Extract displayable text from a Claude assistant message.
 85→ * Content blocks may be text, tool_use, or tool_result — each is
 86→ * handled defensively since the array structure can vary.
 87→ */
 88→function extractText(msg: ClaudeAssistant): string {
 89→  const blocks = msg.message?.content;
 90→  if (!blocks || !Array.isArray(blocks)) return "";
 91→  return blocks
 92→    .map((b) => {
 93→      if (b.type === "text") return b.text;
 94→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 95→      if (b.type === "tool_result") {
 96→        const c = (b as { content?: unknown }).content;
 97→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 98→      }
 99→      return "";
100→    })
101→    .filter(Boolean)
102→    .join("\n");
103→}
104→
105→/** Module-level counter for generating unique message IDs. */
106→let msgCounter = 0;
107→function nextId() {
108→  return `msg-${Date.now()}-${++msgCounter}`;
109→}
110→
111→/**
112→ * Extract a stable dedup key from a relay message, if present.
113→ *
114→ * Claude NDJSON sends cumulative snapshots for two message types:
115→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
116→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
117→ *
118→ * Returns the key or null for non-deduplicable messages.
119→ */
120→function getRelayDedupKey(relayMsg: ServerMessage): string | null {
121→  if (relayMsg.type !== "relay") return null;
122→  const inner = relayMsg.message;
123→  if (inner.type === "assistant") {
124→    return (inner as { message?: { id?: string } }).message?.id ?? null;
125→  }
126→  if (inner.type === "user") {
127→    return (inner as { uuid?: string }).uuid ?? null;
128→  }
129→  return null;
130→}
131→
132→/**
133→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
134→ * Used both for live messages and for replaying message_history.
135→ *
136→ * When a relay message has a stable dedup key (assistant message.id or user uuid),
137→ * that key is used as the ChatMessage `id` so that cumulative snapshots produce
138→ * ChatMessages with the same identity — enabling in-place replacement.
139→ */
140→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
141→  if (relayMsg.type === "relay") {
142→    const msg = relayMsg.message;
143→    const dedupKey = getRelayDedupKey(relayMsg);
144→
145→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
146→      const init = msg as ClaudeSystemInit;
147→      return {
148→        id: `dedup-init-${init.session_id}`,
149→        role: "system",
150→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
151→        timestamp: Date.now(),
152→      };
153→    }
154→
155→    if (msg.type === "user") {
156→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
157→      // Only render human-typed user messages (string content).
158→      // CLI tool_result messages have array content — these are internal
159→      // protocol messages and are only visible in the raw message viewer.
160→      if (typeof rawContent !== "string") return null;
161→      if (!rawContent.trim()) return null;
162→      return {
163→        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
164→        role: "user",
165→        content: rawContent,
166→        timestamp: Date.now(),
167→      };
168→    }
169→
170→    if (msg.type === "assistant") {
171→      const assistant = msg as ClaudeAssistant;
172→      const text = extractText(assistant);
173→      if (!text) return null;
174→
175→      const blocks = assistant.message?.content ?? [];
176→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
177→
178→      // Build a map of tool_use_id → truncated result content
179→      const resultMap = new Map<string, string>();
180→      for (const b of blocks) {
181→        if (b.type === "tool_result" && b.tool_use_id) {
182→          const raw = b.content;
183→          const text = typeof raw === "string" ? raw : JSON.stringify(raw);
184→          // First line, truncated to 120 chars
185→          const firstLine = text.split("\n")[0];
186→          resultMap.set(b.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 120) + "..." : firstLine);
187→        }
188→      }
189→
190→      const toolCalls: ToolCallInfo[] = blocks
191→        .filter((b) => b.type === "tool_use")
192→        .map((b) => ({
193→          name: (b as { name: string }).name,
194→          toolUseId: (b as { id: string }).id,
195→          resultPreview: resultMap.get((b as { id: string }).id),
196→        }));
197→      const isToolOnly = !hasText && toolCalls.length > 0;
198→
199→      return {
200→        id: dedupKey ? `dedup-${dedupKey}` : nextId(),
201→        role: "assistant",
202→        content: text,
203→        timestamp: Date.now(),
204→        toolCalls,
205→        isToolOnly,
206→      };
207→    }
208→
209→    if (msg.type === "result") {
210→      const result = msg as ClaudeResult;
211→      const cost = result.total_cost_usd ?? result.cost_usd ?? 0;
212→      const summary = result.is_error
213→        ? `Error: ${result.error}`
214→        : `Done — ${result.num_turns ?? "?"} turns, $${cost.toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
215→      return {
216→        id: nextId(),
217→        role: "system",
218→        content: summary,
219→        timestamp: Date.now(),
220→      };
221→    }
222→
223→    if (msg.type === "control_request") {
224→      const cr = msg as ClaudeControlRequest;
225→
226→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
227→      if (cr.request.tool_name === "AskUserQuestion") {
228→        const input = cr.request.input as { questions?: UserQuestion[] };
229→        const questions = Array.isArray(input.questions) ? input.questions : [];
230→        return {
231→          id: nextId(),
232→          role: "system",
233→          content: "Question from Claude",
234→          timestamp: Date.now(),
235→          userQuestion: {
236→            requestId: cr.request_id,
237→            questions,
238→          },
239→        };
240→      }
241→
242→      return {
243→        id: nextId(),
244→        role: "system",
245→        content: `Tool approval requested: ${cr.request.tool_name}`,
246→        timestamp: Date.now(),
247→        controlRequest: {
248→          id: cr.request_id,
249→          tool_name: cr.request.tool_name,
250→          input: cr.request.input,
251→          description: cr.request.description,
252→        },
253→      };
254→    }
255→  }
256→
257→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
258→    return {
259→      id: nextId(),
260→      role: "system",
261→      content: `Error: ${relayMsg.error}`,
262→      timestamp: Date.now(),
263→    };
264→  }
265→
266→  return null;
267→}
268→
269→/**
270→ * Find the index of an existing raw message that should be replaced by this relay.
271→ * Searches from the end for speed (cumulative snapshots arrive sequentially).
272→ */
273→function findLastRawIndex(rawMessages: ClaudeMessage[], relay: ServerMessage): number {
274→  if (relay.type !== "relay") return -1;
275→  const inner = relay.message;
276→  if (inner.type === "assistant") {
277→    const id = (inner as { message?: { id?: string } }).message?.id;
278→    if (!id) return -1;
279→    for (let i = rawMessages.length - 1; i >= 0; i--) {
280→      const r = rawMessages[i];
281→      if (r.type === "assistant" && (r as { message?: { id?: string } }).message?.id === id) return i;
282→    }
283→  }
284→  if (inner.type === "user") {
285→    const uuid = (inner as { uuid?: string }).uuid;
286→    if (!uuid) return -1;
287→    for (let i = rawMessages.length - 1; i >= 0; i--) {
288→      const r = rawMessages[i];
289→      if (r.type === "user" && (r as { uuid?: string }).uuid === uuid) return i;
290→    }
291→  }
292→  return -1;
293→}
294→
295→/** Console logger with [thos] prefix for easy filtering. */
296→function log(...args: unknown[]) {
297→  console.log("[thos-ws]", ...args);
298→}
299→
300→export function useWebSocket() {
301→  const wsRef = useRef<WebSocket | null>(null);
302→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
303→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
304→  const closingRef = useRef(false);
305→  const [connected, setConnected] = useState(false);
306→  /** True once we've received the initial agent_list from the server. */
307→  const [initialLoadDone, setInitialLoadDone] = useState(false);
308→
309→  // Multi-agent state
310→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
311→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
312→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
313→
314→  // Task state
315→  const [tasks, setTasks] = useState<Task[]>([]);
316→
317→  // Per-agent deduplication: track count of processed messages per agent
318→  // to avoid duplicating messages already in local state during history replay.
319→  const processedCountRef = useRef<Map<string, number>>(new Map());
320→
321→  // Track which agents have had their history loaded (lazy loading).
322→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
323→
324→  /** Immutably update a single agent's state in the Map. */
325→  const updateAgent = useCallback(
326→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
327→      setAgents((prev) => {
328→        const existing = prev.get(agentId);
329→        if (!existing) return prev;
330→        const next = new Map(prev);
331→        next.set(agentId, updater(existing));
332→        return next;
333→      });
334→    },
335→    []
336→  );
337→
338→  const connect = useCallback(() => {
339→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
340→    if (wsRef.current) {
341→      wsRef.current.close();
342→      wsRef.current = null;
343→    }
344→
345→    // Reset dedup counts on new connection — server will send fresh history
346→    processedCountRef.current.clear();
347→    setInitialLoadDone(false);
348→    setLoadedAgents(new Set());
349→
350→    log("connecting to", WS_URL);
351→    const ws = new WebSocket(WS_URL);
352→    wsRef.current = ws;
353→
354→    ws.onopen = () => {
355→      log("connected");
356→      setConnected(true);
357→    };
358→
359→    ws.onclose = () => {
360→      log("disconnected, closingRef =", closingRef.current);
361→      setConnected(false);
362→      wsRef.current = null;
363→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
364→      if (closingRef.current) return;
365→      // Reconnection guard: clear any existing timer before scheduling
366→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
367→      log("scheduling reconnect in 2s");
368→      reconnectTimer.current = setTimeout(() => connect(), 2000);
369→    };
370→
371→    ws.onerror = (e) => {
372→      log("error", e);
373→      // onclose will fire after onerror, which triggers reconnect
374→    };
375→
376→    ws.onmessage = (event) => {
377→      let data: ServerMessage;
378→      try {
379→        data = JSON.parse(event.data as string);
380→      } catch {
381→        return;
382→      }
383→
384→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
385→
386→      // ── task_list: full task list from server ──
387→      if (data.type === "task_list") {
388→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
389→        setTasks((data as ServerTaskList).tasks);
390→        return;
391→      }
392→
393→      // ── task_updated: single task changed ──
394→      if (data.type === "task_updated") {
395→        const updated = (data as ServerTaskUpdated).task;
396→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
397→        return;
398→      }
399→
400→      // ── task_deleted: remove task ──
401→      if (data.type === "task_deleted") {
402→        const deletedId = (data as ServerTaskDeleted).taskId;
403→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
404→        return;
405→      }
406→
407→      // ── message_history: replay full history from server ──
408→      if (data.type === "message_history") {
409→        const historyMsg = data as ServerMessageHistory;
410→        const agentId = historyMsg.agentId;
411→        const serverMessages = historyMsg.messages;
412→        log("message_history:", agentId, serverMessages.length, "raw msgs");
413→
414→        // Convert all server messages to ChatMessages + extract raw Claude messages
415→        const chatMessages: ChatMessage[] = [];
416→        const rawMessages: ClaudeMessage[] = [];
417→        for (const sm of serverMessages) {
418→          if (sm.type === "relay") {
419→            rawMessages.push(sm.message);
420→          }
421→          const cm = relayChatMessage(agentId, sm);
422→          if (cm) chatMessages.push(cm);
423→        }
424→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
425→
426→        // Always replace local messages with server history (source of truth).
427→        setAgents((prev) => {
428→          const existing = prev.get(agentId);
429→          if (!existing) {
430→            log("message_history:", agentId, "agent not in map yet, creating");
431→            const next = new Map(prev);
432→            next.set(agentId, {
433→              status: "idle",
434→              messages: chatMessages,
435→              rawMessages,
436→              label: "",
437→              tmuxSession: null,
438→              createdAt: 0,
439→            });
440→            return next;
441→          }
442→          const next = new Map(prev);
443→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
444→          return next;
445→        });
446→
447→        processedCountRef.current.set(agentId, chatMessages.length);
448→        setLoadedAgents((prev) => {
449→          if (prev.has(agentId)) return prev;
450→          const next = new Set(prev);
451→          next.add(agentId);
452→          return next;
453→        });
454→        return;
455→      }
456→
457→      // ── history_cleared: wipe local messages for this agent ──
458→      if (data.type === "history_cleared") {
459→        updateAgent(data.agentId, (prev) => ({
460→          ...prev,
461→          messages: [],
462→          rawMessages: [],
463→        }));
464→        processedCountRef.current.set(data.agentId, 0);
465→        return;
466→      }
467→
468→      // ── cli_disconnected: show system message ──
469→      if (data.type === "cli_disconnected") {
470→        updateAgent(data.agentId, (prev) => ({
471→          ...prev,
472→          messages: [
473→            ...prev.messages,
474→            {
475→              id: nextId(),
476→              role: "system",
477→              content: "CLI session ended",
478→              timestamp: Date.now(),
479→            },
480→          ],
481→        }));
482→        return;
483→      }
484→
485→      // ── cli_connected: show system message ──
486→      if (data.type === "cli_connected") {
487→        updateAgent(data.agentId, (prev) => {
488→          const isReconnect = prev.messages.length > 0;
489→          return {
490→            ...prev,
491→            messages: [
492→              ...prev.messages,
493→              {
494→                id: nextId(),
495→                role: "system",
496→                content: isReconnect ? "CLI reconnected" : "CLI connected",
497→                timestamp: Date.now(),
498→              },
499→            ],
500→          };
501→        });
502→        return;
503→      }
504→
505→      // ── agent_list: reconcile sidebar state from server ──
506→      if (data.type === "agent_list") {
507→        const serverAgents = data.agents as AgentInfo[];
508→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
509→        setAgents((prev) => {
510→          const next = new Map(prev);
511→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
512→
513→          // Update or add agents from server
514→          for (const info of serverAgents) {
515→            const existing = next.get(info.agentId);
516→            if (existing) {
517→              next.set(info.agentId, {
518→                ...existing,
519→                status: info.status,
520→                tmuxSession: info.tmuxSession,
521→                label: info.label,
522→              });
523→            } else {
524→              next.set(info.agentId, {
525→                status: info.status,
526→                messages: [],
527→                rawMessages: [],
528→                label: info.label,
529→                tmuxSession: info.tmuxSession,
530→                createdAt: info.createdAt,
531→              });
532→            }
533→          }
534→
535→          // Remove agents no longer on the server
536→          for (const id of next.keys()) {
537→            if (!serverIds.has(id)) {
538→              next.delete(id);
539→            }
540→          }
541→
542→          return next;
543→        });
544→        setAgentOrder(serverAgents.map((a) => a.agentId));
545→        setInitialLoadDone(true);
546→
547→        // No auto-select: leave user on the new-agent creation screen
548→        // until they explicitly pick an agent or spawn a new one.
549→        return;
550→      }
551→
552→      // ── spawned: auto-select the newly created agent ──
553→      if (data.type === "spawned") {
554→        setActiveAgentId(data.agentId);
555→        return;
556→      }
557→
558→      // ── status: update a specific agent's status ──
559→      if (data.type === "status") {
560→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
561→        return;
562→      }
563→
564→      // ── error: append to agent's message list ──
565→      if (data.type === "error") {
566→        updateAgent(data.agentId, (prev) => ({
567→          ...prev,
568→          messages: [
569→            ...prev.messages,
570→            {
571→              id: nextId(),
572→              role: "system",
573→              content: `Error: ${data.error}`,
574→              timestamp: Date.now(),
575→            },
576→          ],
577→        }));
578→        // Track processed count for dedup
579→        processedCountRef.current.set(
580→          data.agentId,
581→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
582→        );
583→        return;
584→      }
585→
586→      // ── relay: append or replace claude message in agent's history ──
587→      if (data.type === "relay") {
588→        const agentId = data.agentId;
589→        const rawMsg = data.message;
590→        const chatMsg = relayChatMessage(agentId, data);
591→        const dedupKey = getRelayDedupKey(data);
592→
593→        updateAgent(agentId, (prev) => {
594→          // Dedup raw messages: replace previous snapshot with same dedup key
595→          let nextRaw: ClaudeMessage[];
596→          if (dedupKey) {
597→            const existingIdx = findLastRawIndex(prev.rawMessages, data);
598→            if (existingIdx >= 0) {
599→              nextRaw = [...prev.rawMessages];
600→              nextRaw[existingIdx] = rawMsg;
601→            } else {
602→              nextRaw = [...prev.rawMessages, rawMsg];
603→            }
604→          } else {
605→            nextRaw = [...prev.rawMessages, rawMsg];
606→          }
607→
608→          if (!chatMsg) return { ...prev, rawMessages: nextRaw };
609→
610→          // Dedup chat messages: if this relay has a stable dedup key,
611→          // replace the existing ChatMessage with the same id instead of appending.
612→          let nextMessages: ChatMessage[];
613→          if (chatMsg.id.startsWith("dedup-")) {
614→            const existingIdx = prev.messages.findIndex((m) => m.id === chatMsg.id);
615→            if (existingIdx >= 0) {
616→              nextMessages = [...prev.messages];
617→              nextMessages[existingIdx] = chatMsg;
618→            } else {
619→              nextMessages = [...prev.messages, chatMsg];
620→            }
621→          } else {
622→            nextMessages = [...prev.messages, chatMsg];
623→          }
624→
625→          return { ...prev, rawMessages: nextRaw, messages: nextMessages };
626→        });
627→        if (chatMsg) {
628→          // Track processed count for dedup
629→          processedCountRef.current.set(
630→            agentId,
631→            (processedCountRef.current.get(agentId) ?? 0) + 1
632→          );
633→        }
634→        return;
635→      }
636→    };
637→  }, [updateAgent]);
638→
639→  useEffect(() => {
640→    closingRef.current = false;
641→    connect();
642→    return () => {
643→      closingRef.current = true;
644→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
645→      wsRef.current?.close();
646→    };
647→  }, [connect]);
648→
649→  const send = useCallback((data: object) => {
650→    if (wsRef.current?.readyState === WebSocket.OPEN) {
651→      wsRef.current.send(JSON.stringify(data));
652→    }
653→  }, []);
654→
655→  // Request history for the active agent if not already loaded.
656→  useEffect(() => {
657→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
658→    log("requesting history for", activeAgentId);
659→    send({ type: "request_history", agentId: activeAgentId });
660→  }, [activeAgentId, loadedAgents, send]);
661→
662→  const spawnAgent = useCallback(
663→    (prompt: string) => {
664→      send({ type: "spawn", prompt });
665→    },
666→    [send]
667→  );
668→
669→  const sendMessage = useCallback(
670→    (content: string) => {
671→      if (!activeAgentId) return;
672→      // Optimistically add user message to local state
673→      updateAgent(activeAgentId, (prev) => ({
674→        ...prev,
675→        messages: [
676→          ...prev.messages,
677→          {
678→            id: nextId(),
679→            role: "user",
680→            content,
681→            timestamp: Date.now(),
682→          },
683→        ],
684→      }));
685→      send({ type: "send_message", agentId: activeAgentId, content });
686→    },
687→    [send, activeAgentId, updateAgent]
688→  );
689→
690→  const respondToControl = useCallback(
691→    (requestId: string, allow: boolean) => {
692→      if (!activeAgentId) return;
693→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
694→      updateAgent(activeAgentId, (prev) => ({
695→        ...prev,
696→        messages: prev.messages.map((m) =>
697→          m.controlRequest?.id === requestId
698→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
699→            : m
700→        ),
701→      }));
702→    },
703→    [send, activeAgentId, updateAgent]
704→  );
705→
706→  /** Respond to an AskUserQuestion control request with the user's selections. */
707→  const respondToUserQuestion = useCallback(
708→    (requestId: string, answers: Record<string, string>) => {
709→      if (!activeAgentId) return;
710→      send({
711→        type: "control_response",
712→        agentId: activeAgentId,
713→        request_id: requestId,
714→        allow: true,
715→        answers,
716→      });
717→      updateAgent(activeAgentId, (prev) => ({
718→        ...prev,
719→        messages: prev.messages.map((m) =>
720→          m.userQuestion?.requestId === requestId
721→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
722→            : m
723→        ),
724→      }));
725→    },
726→    [send, activeAgentId, updateAgent]
727→  );
728→
729→  // ── Agent management actions ──────────────────────────────────────────────
730→
731→  const killAgent = useCallback(
732→    (agentId: string) => {
733→      send({ type: "kill_agent", agentId });
734→    },
735→    [send]
736→  );
737→
738→  const deleteAgent = useCallback(
739→    (agentId: string) => {
740→      send({ type: "delete_agent", agentId });
741→      // Deselect if we just deleted the active agent
742→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
743→    },
744→    [send]
745→  );
746→
747→  const renameAgent = useCallback(
748→    (agentId: string, label: string) => {
749→      send({ type: "rename_agent", agentId, label });
750→    },
751→    [send]
752→  );
753→
754→  const clearHistory = useCallback(
755→    (agentId: string) => {
756→      send({ type: "clear_history", agentId });
757→    },
758→    [send]
759→  );
760→
761→  // ── Task actions ──────────────────────────────────────────────────────────
762→
763→  const createTask = useCallback(
764→    (title: string, description: string, priority: TaskPriority) => {
765→      send({ type: "create_task", title, description, priority });
766→    },
767→    [send]
768→  );
769→
770→  const updateTask = useCallback(
771→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
772→      send({ type: "update_task", taskId, updates });
773→    },
774→    [send]
775→  );
776→
777→  const deleteTask = useCallback(
778→    (taskId: string) => {
779→      send({ type: "delete_task", taskId });
780→    },
781→    [send]
782→  );
783→
784→  const delegateTask = useCallback(
785→    (taskId: string) => {
786→      send({ type: "delegate_task", taskId });
787→    },
788→    [send]
789→  );
790→
791→  // Derived values for the active agent
792→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
793→  const activeStatus = useMemo<AgentStatus>(
794→    () => activeAgent?.status ?? "idle",
795→    [activeAgent?.status]
796→  );
797→  const activeMessages = useMemo<ChatMessage[]>(
798→    () => activeAgent?.messages ?? [],
799→    [activeAgent?.messages]
800→  );
801→  const activeRawMessages = useMemo<ClaudeMessage[]>(
802→    () => activeAgent?.rawMessages ?? [],
803→    [activeAgent?.rawMessages]
804→  );
805→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
806→
807→  return {
808→    connected,
809→    initialLoadDone,
810→    historyLoading,
811→    agents,
812→    agentOrder,
813→    activeAgentId,
814→    setActiveAgentId,
815→    activeStatus,
816→    activeMessages,
817→    activeRawMessages,
818→    spawnAgent,
819→    sendMessage,
820→    respondToControl,
821→    respondToUserQuestion,
822→    killAgent,
823→    deleteAgent,
824→    renameAgent,
825→    clearHistory,
826→    tasks,
827→    createTask,
828→    updateTask,
829→    deleteTask,
830→    delegateTask,
831→  };
832→}
