  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`.
 37→ * 4. Server immediately sends the pending prompt as a `user` message.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * Note: CLI 2.1.41 sent `hook_started`/`hook_response` before `init`; CLI 2.1.42+
 44→ * waits for the server to send the first user message. The `hook_response` handler
 45→ * is kept as a fallback for older CLI versions.
 46→ *
 47→ * ## Resilience features
 48→ *
 49→ * - **Server-side message history** — every relay message is stored per-agent.
 50→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 51→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 52→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 53→ *   can reconnect to the new server if they retry their WebSocket connection.
 54→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 55→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 56→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 57→ */
 58→import { WebSocketServer, WebSocket } from "ws";
 59→import { execSync, spawn } from "child_process";
 60→import { randomBytes } from "crypto";
 61→import type { IncomingMessage } from "http";
 62→import type {
 63→  BrowserMessage,
 64→  ClaudeMessage,
 65→  ServerMessage,
 66→  AgentStatus,
 67→  AgentInfo,
 68→  Task,
 69→} from "../lib/types";
 70→import { SessionStore, type PersistedAgent } from "./session-store";
 71→import { TaskStore } from "./task-store";
 72→
 73→const PORT = 9900;
 74→const TMUX_SESSION_PREFIX = "thos-agent";
 75→
 76→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 77→function isAllowedIP(ip: string | undefined): boolean {
 78→  if (!ip) return false;
 79→  // Strip IPv6-mapped IPv4 prefix
 80→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 81→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 82→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 83→  const parts = addr.split(".");
 84→  if (parts.length !== 4) return false;
 85→  const first = parseInt(parts[0], 10);
 86→  const second = parseInt(parts[1], 10);
 87→  return first === 100 && second >= 64 && second <= 127;
 88→}
 89→
 90→const wss = new WebSocketServer({
 91→  port: PORT,
 92→  verifyClient: (info) => {
 93→    const ip = info.req.socket.remoteAddress;
 94→    const allowed = isAllowedIP(ip);
 95→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 96→    return allowed;
 97→  },
 98→});
 99→const store = new SessionStore();
100→
101→// ── Multi-agent state ──────────────────────────────────────────────────────
102→
103→interface AgentState {
104→  agentId: string;
105→  claudeSocket: WebSocket | null;
106→  tmuxSession: string | null;
107→  pendingPrompt: string | null;
108→  status: AgentStatus;
109→  label: string;
110→  createdAt: number;
111→  /** Captured from system/init, used in subsequent user messages. */
112→  sessionId: string | null;
113→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
114→  pendingControlRequests: Map<string, Record<string, unknown>>;
115→  /** All messages sent to the browser for this agent (source of truth). */
116→  messageHistory: ServerMessage[];
117→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
118→  pendingMessages: string[];
119→}
120→
121→const agents = new Map<string, AgentState>();
122→const taskStore = new TaskStore();
123→const tasks = new Map<string, Task>();
124→
125→/** All active browser connections (supports multiple tabs). */
126→const browserSockets = new Set<WebSocket>();
127→
128→/** Generate a short random agent ID. */
129→function newAgentId(): string {
130→  return randomBytes(4).toString("hex");
131→}
132→
133→// ── tmux helpers ───────────────────────────────────────────────────────────
134→
135→/** Return the set of currently alive tmux session names matching the thos prefix. */
136→function listAliveTmuxSessions(): Set<string> {
137→  try {
138→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
139→      encoding: "utf-8",
140→    }).trim();
141→    if (!output) return new Set();
142→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
143→  } catch {
144→    return new Set();
145→  }
146→}
147→
148→// ── Persistence helpers ────────────────────────────────────────────────────
149→
150→/** Build a PersistedAgent snapshot from live state. */
151→function toPersistedAgent(agent: AgentState): PersistedAgent {
152→  return {
153→    id: agent.agentId,
154→    state: {
155→      agentId: agent.agentId,
156→      status: agent.status,
157→      tmuxSession: agent.tmuxSession,
158→      label: agent.label,
159→      createdAt: agent.createdAt,
160→      sessionId: agent.sessionId,
161→    },
162→    messageHistory: agent.messageHistory,
163→  };
164→}
165→
166→/**
167→ * Compact a message history by deduplicating cumulative snapshots.
168→ * Keeps only the last version of each assistant/user message ID.
169→ * Called on restore to shrink legacy bloated histories.
170→ */
171→function compactHistory(history: ServerMessage[]): ServerMessage[] {
172→  // Build a map of msgId → last index
173→  const lastIndex = new Map<string, number>();
174→  for (let i = 0; i < history.length; i++) {
175→    const id = getRelayMessageId(history[i]);
176→    if (id) lastIndex.set(id, i);
177→  }
178→  // Keep only messages that are either non-deduplicable or the last occurrence
179→  return history.filter((msg, i) => {
180→    const id = getRelayMessageId(msg);
181→    if (!id) return true; // non-relay or no message ID — always keep
182→    return lastIndex.get(id) === i;
183→  });
184→}
185→
186→/** Persist agent state (debounced — use for streaming events). */
187→function persistAgent(agent: AgentState) {
188→  store.save(toPersistedAgent(agent));
189→}
190→
191→/** Persist agent state immediately (use for critical state changes). */
192→function persistAgentSync(agent: AgentState) {
193→  store.saveSync(toPersistedAgent(agent));
194→}
195→
196→// ── Restore from disk on startup ───────────────────────────────────────────
197→
198→function restoreAgents() {
199→  const persisted = store.loadAll();
200→  const aliveSessions = listAliveTmuxSessions();
201→
202→  for (const p of persisted) {
203→    const agent: AgentState = {
204→      agentId: p.state.agentId,
205→      claudeSocket: null,
206→      tmuxSession: p.state.tmuxSession,
207→      pendingPrompt: null,
208→      status: p.state.status,
209→      label: p.state.label,
210→      createdAt: p.state.createdAt,
211→      sessionId: p.state.sessionId,
212→      pendingControlRequests: new Map(),
213→      messageHistory: compactHistory(p.messageHistory),
214→      pendingMessages: [],
215→    };
216→
217→    // Determine status for agents that were active when the server last ran
218→    if (agent.status !== "done" && agent.status !== "error") {
219→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
220→      if (tmuxAlive) {
221→        // tmux session still alive — CLI may reconnect to this server
222→        agent.status = "disconnected";
223→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
224→      } else {
225→        // tmux session gone — agent is archived
226→        agent.status = "done";
227→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
228→      }
229→    }
230→
231→    agents.set(agent.agentId, agent);
232→    const originalCount = p.messageHistory.length;
233→    const compactedCount = agent.messageHistory.length;
234→    const saved = originalCount - compactedCount;
235→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
236→
237→    // Persist compacted history back to disk
238→    if (saved > 0) {
239→      persistAgentSync(agent);
240→    }
241→  }
242→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
243→}
244→
245→restoreAgents();
246→
247→// ── Task restore + helpers ────────────────────────────────────────────────
248→
249→function restoreTasks() {
250→  const persisted = taskStore.loadAll();
251→  for (const t of persisted) {
252→    tasks.set(t.id, t);
253→  }
254→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
255→}
256→
257→restoreTasks();
258→
259→/** Build the full task list sorted by creation time (newest first). */
260→function buildTaskList(): Task[] {
261→  return Array.from(tasks.values()).sort((a, b) => b.createdAt - a.createdAt);
262→}
263→
264→/** Send the full task list to all browsers. */
265→function broadcastTaskList() {
266→  const payload = JSON.stringify({ type: "task_list", tasks: buildTaskList() });
267→  for (const ws of browserSockets) {
268→    if (ws.readyState === WebSocket.OPEN) {
269→      ws.send(payload);
270→    }
271→  }
272→}
273→
274→/** Persist all tasks to disk (sync). */
275→function persistTasks() {
276→  taskStore.saveSync(Array.from(tasks.values()));
277→}
278→
279→// ── Helpers ────────────────────────────────────────────────────────────────
280→
281→/** Send a JSON message to all connected browsers. */
282→function sendToBrowser(msg: ServerMessage) {
283→  const payload = JSON.stringify(msg);
284→  for (const ws of browserSockets) {
285→    if (ws.readyState === WebSocket.OPEN) {
286→      ws.send(payload);
287→    }
288→  }
289→}
290→
291→/** Build a snapshot of all agents for the sidebar. */
292→function buildAgentList(): AgentInfo[] {
293→  return Array.from(agents.values()).map((a) => ({
294→    agentId: a.agentId,
295→    status: a.status,
296→    tmuxSession: a.tmuxSession,
297→    label: a.label,
298→    createdAt: a.createdAt,
299→  }));
300→}
301→
302→/** Send the full agent list to all browsers. */
303→function broadcastAgentList() {
304→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
305→}
306→
307→/** Update an agent's status, notify browsers, broadcast list, and persist. */
308→function setAgentStatus(agentId: string, status: AgentStatus) {
309→  const agent = agents.get(agentId);
310→  if (!agent) return;
311→  agent.status = status;
312→  sendToBrowser({ type: "status", agentId, status });
313→  broadcastAgentList();
314→  persistAgentSync(agent);
315→}
316→
317→/**
318→ * Extract a stable dedup key from a relay message, if present.
319→ *
320→ * Claude NDJSON sends cumulative snapshots for two message types:
321→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
322→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
323→ *
324→ * We deduplicate by replacing the previous snapshot in `messageHistory`
325→ * instead of appending, reducing storage from O(n²) to O(n).
326→ */
327→function getRelayMessageId(msg: ServerMessage): string | null {
328→  if (msg.type !== "relay") return null;
329→  const inner = msg.message;
330→  if (inner.type === "assistant") {
331→    return (inner as { message?: { id?: string } }).message?.id ?? null;
332→  }
333→  if (inner.type === "user") {
334→    return (inner as { uuid?: string }).uuid ?? null;
335→  }
336→  return null;
337→}
338→
339→/**
340→ * Record a message in the agent's history and send to all browsers.
341→ *
342→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
343→ * previous snapshot with the same message ID instead of appending. This keeps
344→ * only the final version of each message, dramatically reducing file sizes
345→ * (e.g. 38 MB → ~1 MB for a typical session).
346→ */
347→function recordAndSend(agentId: string, msg: ServerMessage) {
348→  const agent = agents.get(agentId);
349→  if (agent) {
350→    const msgId = getRelayMessageId(msg);
351→    if (msgId) {
352→      // Replace previous snapshot with same message ID (search from end for speed)
353→      let replaced = false;
354→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
355→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
356→          agent.messageHistory[i] = msg;
357→          replaced = true;
358→          break;
359→        }
360→      }
361→      if (!replaced) {
362→        agent.messageHistory.push(msg);
363→      }
364→    } else {
365→      agent.messageHistory.push(msg);
366→    }
367→    persistAgent(agent); // debounced — streaming messages come fast
368→  }
369→  sendToBrowser(msg);
370→}
371→
372→// ── Agent lifecycle ────────────────────────────────────────────────────────
373→
374→/**
375→ * Stop a running agent by killing its tmux session and closing the CLI socket.
376→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
377→ */
378→function stopAgent(agentId: string) {
379→  const agent = agents.get(agentId);
380→  if (!agent) return;
381→
382→  if (agent.tmuxSession) {
383→    try {
384→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
385→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
386→    } catch {
387→      // Session may already be dead
388→    }
389→  }
390→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
391→    agent.claudeSocket.close();
392→  }
393→  agent.claudeSocket = null;
394→  setAgentStatus(agentId, "done");
395→}
396→
397→/**
398→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
399→ */
400→function deleteAgent(agentId: string) {
401→  const agent = agents.get(agentId);
402→  if (!agent) return;
403→
404→  if (agent.tmuxSession) {
405→    try {
406→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
407→    } catch {}
408→  }
409→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
410→    agent.claudeSocket.close();
411→  }
412→  agents.delete(agentId);
413→  store.remove(agentId);
414→  broadcastAgentList();
415→}
416→
417→/**
418→ * Spawn a new Claude CLI process inside a tmux session.
419→ *
420→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
421→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
422→ */
423→function spawnClaude(prompt: string): string {
424→  const agentId = newAgentId();
425→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
426→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
427→
428→  const agent: AgentState = {
429→    agentId,
430→    claudeSocket: null,
431→    tmuxSession: null,
432→    pendingPrompt: prompt,
433→    status: "spawning",
434→    label,
435→    createdAt: Date.now(),
436→    sessionId: null,
437→    pendingControlRequests: new Map(),
438→    messageHistory: [],
439→    pendingMessages: [],
440→  };
441→  agents.set(agentId, agent);
442→
443→  // Notify browsers
444→  sendToBrowser({ type: "spawned", agentId });
445→  broadcastAgentList();
446→  persistAgentSync(agent);
447→
448→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
449→  // tmux new-session runs detached (-d) so spawn() returns immediately.
450→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
451→
452→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
453→    stdio: "ignore",
454→  });
455→
456→  tmux.on("error", (err) => {
457→    console.error("[tmux spawn error]", err);
458→    setAgentStatus(agentId, "error");
459→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
460→  });
461→
462→  tmux.on("exit", (code) => {
463→    if (code !== 0) {
464→      console.error(`[tmux] new-session exited with code ${code}`);
465→      setAgentStatus(agentId, "error");
466→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
467→      return;
468→    }
469→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
470→    agent.tmuxSession = sessionName;
471→    broadcastAgentList();
472→    persistAgentSync(agent);
473→  });
474→
475→  return agentId;
476→}
477→
478→// ── Message handlers ───────────────────────────────────────────────────────
479→
480→/**
481→ * Process an incoming NDJSON message from a specific Claude CLI.
482→ *
483→ * Status flow matches the Companion protocol:
484→ * - hook_response → send pending prompt → "thinking"
485→ * - system/init   → "connected" + capture session_id
486→ * - assistant      → "thinking"
487→ * - result         → "connected" (CLI stays alive for multi-turn)
488→ * - CLI disconnect → "done" (handled in connection close handler)
489→ */
490→function handleClaudeMessage(agentId: string, raw: string) {
491→  const agent = agents.get(agentId);
492→  if (!agent) return;
493→
494→  let msg: ClaudeMessage;
495→  try {
496→    msg = JSON.parse(raw);
497→  } catch {
498→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
499→    return;
500→  }
501→
502→  // Silently ignore keep_alive messages
503→  if (msg.type === "keep_alive") return;
504→
505→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
506→
507→  // After hook_response, send the pending prompt
508→  if (
509→    msg.type === "system" &&
510→    (msg as { subtype?: string }).subtype === "hook_response" &&
511→    agent.pendingPrompt &&
512→    agent.claudeSocket?.readyState === WebSocket.OPEN
513→  ) {
514→    const userMsg = JSON.stringify({
515→      type: "user",
516→      message: { role: "user", content: agent.pendingPrompt },
517→      parent_tool_use_id: null,
518→      session_id: agent.sessionId ?? "",
519→    });
520→    console.log(`[server → claude:${agentId}]`, userMsg);
521→    agent.claudeSocket.send(userMsg + "\n");
522→
523→    // Record the initial user message in history so it appears in chat
524→    recordAndSend(agentId, {
525→      type: "relay",
526→      agentId,
527→      message: { type: "user", message: { role: "user", content: agent.pendingPrompt } },
528→    } as ServerMessage);
529→
530→    agent.pendingPrompt = null;
531→    setAgentStatus(agentId, "thinking");
532→  }
533→
534→  // Track status based on message type
535→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
536→    // Capture session_id for subsequent user messages
537→    const isFirstInit = agent.sessionId === null;
538→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
539→    setAgentStatus(agentId, "connected");
540→
541→    // Only relay the first system/init — subsequent ones are redundant
542→    // (CLI re-sends init on every turn)
543→    if (!isFirstInit) return;
544→  } else if (msg.type === "assistant") {
545→    setAgentStatus(agentId, "thinking");
546→  } else if (msg.type === "result") {
547→    // CLI stays alive after result — ready for the next turn.
548→    // Status only goes to "done" when the CLI WebSocket actually closes.
549→    setAgentStatus(agentId, "connected");
550→  }
551→
552→  // Store control_request inputs for building proper responses later
553→  if (msg.type === "control_request") {
554→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
555→    if (cr.request_id && cr.request?.input) {
556→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
557→    }
558→  }
559→
560→  // Record in history and relay to browsers
561→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
562→}
563→
564→/**
565→ * Process an incoming JSON message from the browser.
566→ * - `spawn`: create a new agent (does NOT kill others).
567→ * - `send_message`: forward a follow-up user message to the specified agent.
568→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
569→ * - `kill_agent`: stop the CLI and tmux session.
570→ * - `delete_agent`: permanently remove an agent.
571→ * - `rename_agent`: update an agent's label.
572→ * - `clear_history`: wipe an agent's message history.
573→ * - `request_history`: send message history for a single agent (lazy loading).
574→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
575→ */
576→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
577→  let msg: BrowserMessage;
578→  try {
579→    msg = JSON.parse(raw);
580→  } catch {
581→    console.error("[browser] invalid JSON:", raw);
582→    return;
583→  }
584→
585→  console.log("[browser →]", msg.type);
586→
587→  switch (msg.type) {
588→    case "spawn":
589→      spawnClaude(msg.prompt);
590→      break;
591→
592→    case "send_message": {
593→      const agent = agents.get(msg.agentId);
594→      if (!agent) {
595→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
596→        break;
597→      }
598→
599→      // Record the user message in history so it persists across reloads.
600→      // Do NOT broadcast — the sending browser already has it optimistically,
601→      // and other browsers will get it when they request_history.
602→      agent.messageHistory.push({
603→        type: "relay",
604→        agentId: msg.agentId,
605→        message: { type: "user", message: { role: "user", content: msg.content } },
606→      } as ServerMessage);
607→      persistAgent(agent);
608→
609→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
610→        const userMsg = JSON.stringify({
611→          type: "user",
612→          message: { role: "user", content: msg.content },
613→          parent_tool_use_id: null,
614→          session_id: agent.sessionId ?? "",
615→        });
616→        agent.claudeSocket.send(userMsg + "\n");
617→        setAgentStatus(msg.agentId, "thinking");
618→      } else {
619→        // Queue message for delivery when CLI reconnects
620→        const userMsg = JSON.stringify({
621→          type: "user",
622→          message: { role: "user", content: msg.content },
623→          parent_tool_use_id: null,
624→          session_id: agent.sessionId ?? "",
625→        });
626→        agent.pendingMessages.push(userMsg);
627→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
628→        persistAgentSync(agent);
629→      }
630→      break;
631→    }
632→
633→    case "control_response": {
634→      const agent = agents.get(msg.agentId);
635→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
636→        // Retrieve the original tool input to include as updatedInput (required by protocol)
637→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
638→        agent.pendingControlRequests.delete(msg.request_id);
639→
640→        // If the browser sent answers (from AskUserQuestion), merge them into the input
641→        const answers = (msg as { answers?: Record<string, string> }).answers;
642→        const updatedInput = answers
643→          ? { ...originalInput, answers }
644→          : originalInput;
645→
646→        const response = JSON.stringify({
647→          type: "control_response",
648→          response: {
649→            subtype: "success",
650→            request_id: msg.request_id,
651→            response: msg.allow
652→              ? { behavior: "allow", updatedInput }
653→              : { behavior: "deny", message: "Denied by user" },
654→          },
655→        });
656→        agent.claudeSocket.send(response + "\n");
657→      }
658→      break;
659→    }
660→
661→    case "kill_agent":
662→      stopAgent(msg.agentId);
663→      break;
664→
665→    case "delete_agent":
666→      deleteAgent(msg.agentId);
667→      break;
668→
669→    case "rename_agent": {
670→      const agent = agents.get(msg.agentId);
671→      if (!agent) break;
672→      agent.label = msg.label;
673→      broadcastAgentList();
674→      persistAgentSync(agent);
675→      break;
676→    }
677→
678→    case "clear_history": {
679→      const agent = agents.get(msg.agentId);
680→      if (!agent) break;
681→      agent.messageHistory = [];
682→      persistAgentSync(agent);
683→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
684→      break;
685→    }
686→
687→    case "request_history": {
688→      console.log(`[browser] request_history for ${msg.agentId}`);
689→      sendHistoryToSocket(senderWs, msg.agentId);
690→      break;
691→    }
692→
693→    case "create_task": {
694→      const taskId = randomBytes(4).toString("hex");
695→      const task: Task = {
696→        id: taskId,
697→        title: msg.title,
698→        description: msg.description,
699→        status: "todo",
700→        priority: msg.priority,
701→        agentId: null,
702→        createdAt: Date.now(),
703→        updatedAt: Date.now(),
704→      };
705→      tasks.set(taskId, task);
706→      persistTasks();
707→      broadcastTaskList();
708→      break;
709→    }
710→
711→    case "update_task": {
712→      const task = tasks.get(msg.taskId);
713→      if (!task) break;
714→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
715→      persistTasks();
716→      broadcastTaskList();
717→
718→      // Archive the linked agent when a task is marked as done
719→      if (task.status === "done" && task.agentId) {
720→        const linkedAgent = agents.get(task.agentId);
721→        if (linkedAgent && linkedAgent.status !== "done" && linkedAgent.status !== "error") {
722→          stopAgent(task.agentId);
723→        }
724→      }
725→      break;
726→    }
727→
728→    case "delete_task": {
729→      tasks.delete(msg.taskId);
730→      persistTasks();
731→      broadcastTaskList();
732→      break;
733→    }
734→
735→    case "delegate_task": {
736→      const task = tasks.get(msg.taskId);
737→      if (!task) break;
738→      const prompt = `Task: ${task.title}\n\n${task.description}`;
739→      const agentId = spawnClaude(prompt);
740→      task.agentId = agentId;
741→      task.status = "in-progress";
742→      task.updatedAt = Date.now();
743→      persistTasks();
744→      broadcastTaskList();
745→      break;
746→    }
747→  }
748→}
749→
750→// ── Send message history to a single browser socket ────────────────────────
751→
752→/** Send initial state (agent list + tasks) to a newly connected browser. */
753→function sendFullStateToSocket(ws: WebSocket) {
754→  if (ws.readyState !== WebSocket.OPEN) return;
755→
756→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
757→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
758→
759→  // Task list
760→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
761→}
762→
763→/** Send message history for a single agent to a specific browser socket. */
764→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
765→  const agent = agents.get(agentId);
766→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
767→  ws.send(
768→    JSON.stringify({
769→      type: "message_history",
770→      agentId: agent.agentId,
771→      messages: agent.messageHistory,
772→    })
773→  );
774→}
775→
776→// ── Connection handler — route by URL path ────────────────────────────────
777→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
778→  const path = req.url ?? "/";
779→  console.log(`[ws connected] path=${path}`);
780→
781→  if (path === "/browser") {
782→    // Send full state BEFORE adding to browserSockets so that live
783→    // relay broadcasts don't interleave with the history replay.
784→    sendFullStateToSocket(ws);
785→    browserSockets.add(ws);
786→
787→    ws.on("message", (data) => {
788→      handleBrowserMessage(data.toString(), ws);
789→    });
790→
791→    ws.on("close", () => {
792→      console.log("[browser disconnected]");
793→      browserSockets.delete(ws);
794→      // Do NOT kill agents — keep them alive for reconnect
795→    });
796→  } else if (path.startsWith("/claude/")) {
797→    // Parse agentId from /claude/<agentId>
798→    const agentId = path.slice("/claude/".length);
799→    const agent = agents.get(agentId);
800→
801→    if (!agent) {
802→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
803→      ws.close();
804→      return;
805→    }
806→
807→    agent.claudeSocket = ws;
808→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
809→
810→    // Notify browsers that CLI is connected
811→    sendToBrowser({ type: "cli_connected", agentId });
812→
813→    // Flush any pending messages queued while CLI was disconnected
814→    if (agent.pendingMessages.length > 0) {
815→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
816→      for (const queued of agent.pendingMessages) {
817→        ws.send(queued + "\n");
818→      }
819→      agent.pendingMessages = [];
820→      persistAgentSync(agent);
821→    }
822→
823→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
824→    // server to send the first user message rather than emitting
825→    // hook_started/hook_response on connect.
826→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
827→      const userMsg = JSON.stringify({
828→        type: "user",
829→        message: { role: "user", content: agent.pendingPrompt },
830→        parent_tool_use_id: null,
831→        session_id: agent.sessionId ?? "",
832→      });
833→      console.log(`[server → claude:${agentId}] sending pending prompt`);
834→      ws.send(userMsg + "\n");
835→
836→      // Record the initial user message in history so it appears in chat
837→      recordAndSend(agentId, {
838→        type: "relay",
839→        agentId,
840→        message: { type: "user", message: { role: "user", content: agent.pendingPrompt } },
841→      } as ServerMessage);
842→
843→      agent.pendingPrompt = null;
844→      setAgentStatus(agentId, "thinking");
845→    }
846→
847→    ws.on("message", (data) => {
848→      handleClaudeMessage(agentId, data.toString());
849→    });
850→
851→    ws.on("close", () => {
852→      console.log(`[claude:${agentId} CLI disconnected]`);
853→      if (agent.claudeSocket === ws) {
854→        agent.claudeSocket = null;
855→        if (agent.status !== "error") {
856→          setAgentStatus(agentId, "done");
857→          sendToBrowser({ type: "cli_disconnected", agentId });
858→
859→          // Auto-complete any task linked to this agent
860→          for (const task of tasks.values()) {
861→            if (task.agentId === agentId && task.status !== "done") {
862→              task.status = "done";
863→              task.updatedAt = Date.now();
864→              persistTasks();
865→              broadcastTaskList();
866→              break;
867→            }
868→          }
869→        }
870→      }
871→    });
872→  } else {
873→    console.log(`[ws] unknown path: ${path}, closing`);
874→    ws.close();
875→  }
876→});
877→
878→// ── Graceful shutdown ─────────────────────────────────────────────────────
879→
880→function shutdown() {
881→  console.log("[ws server] shutting down...");
882→
883→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
884→  // so CLI processes can reconnect if the server restarts.
885→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
886→  store.flushAll(allPersisted);
887→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
888→
889→  taskStore.flush(Array.from(tasks.values()));
890→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
891→
892→  wss.close();
893→  process.exit(0);
894→}
895→
896→process.on("SIGTERM", shutdown);
897→process.on("SIGINT", shutdown);
898→
899→console.log(`[ws server] listening on port ${PORT}`);
