  9→
 10→import type { ChatMessage } from "@/lib/types";
 11→import { cn } from "@/lib/utils";
 12→import { Check, Copy } from "lucide-react";
 13→import { useCallback, useEffect, useState } from "react";
 14→import Markdown from "react-markdown";
 15→import remarkGfm from "remark-gfm";
 16→
 17→/** Format a timestamp as a relative string like "just now", "2m ago", "1h ago". */
 18→function formatRelativeTime(ts: number): string {
 19→  const diff = Date.now() - ts;
 20→  if (diff < 60_000) return "just now";
 21→  const mins = Math.floor(diff / 60_000);
 22→  if (mins < 60) return `${mins}m ago`;
 23→  const hrs = Math.floor(mins / 60);
 24→  if (hrs < 24) return `${hrs}h ago`;
 25→  const days = Math.floor(hrs / 24);
 26→  return `${days}d ago`;
 27→}
 28→
 29→/** Timestamp showing "12:34 PM (2m ago)" that updates every 30s. */
 30→function MessageTime({ timestamp, className }: { timestamp: number; className?: string }) {
 31→  const [, setTick] = useState(0);
 32→
 33→  useEffect(() => {
 34→    const id = setInterval(() => setTick((t) => t + 1), 30_000);
 35→    return () => clearInterval(id);
 36→  }, []);
 37→
 38→  const absolute = new Date(timestamp).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
 39→  const relative = formatRelativeTime(timestamp);
 40→
 41→  return (
 42→    <time
 43→      dateTime={new Date(timestamp).toISOString()}
 44→      title={new Date(timestamp).toLocaleString()}
 45→      className={className}
 46→    >
 47→      {absolute} ({relative})
 48→    </time>
 49→  );
 50→}
 51→
 52→function CopyButton({ text }: { text: string }) {
 53→  const [copied, setCopied] = useState(false);
 54→
 55→  const copy = useCallback(() => {
 56→    navigator.clipboard.writeText(text).then(() => {
 57→      setCopied(true);
 58→      setTimeout(() => setCopied(false), 1500);
 59→    });
 60→  }, [text]);
 61→
 62→  return (
 63→    <button
 64→      onClick={copy}
 65→      className="absolute top-1.5 right-1.5 opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded-md bg-muted/80 hover:bg-muted text-muted-foreground hover:text-foreground"
 66→      aria-label="Copy message"
 67→    >
 68→      {copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
 69→    </button>
 70→  );
 71→}
 72→
 73→export function Message({ message }: { message: ChatMessage }) {
 74→  if (message.role === "system") {
 75→    return (
 76→      <div className="py-1 text-center text-xs italic text-muted-foreground">
 77→        {message.content}
 78→      </div>
 79→    );
 80→  }
 81→
 82→  const isUser = message.role === "user";
 83→
 84→  return (
 85→    <div className={cn("flex", isUser ? "justify-end" : "justify-start")}>
 86→      <div className={cn("flex flex-col", isUser ? "items-end" : "items-start")}>
 87→        <div
 88→          className={cn(
 89→            "group relative max-w-[90%] md:max-w-[80%] rounded-lg px-3 py-2 text-sm",
 90→            isUser
 91→              ? "bg-primary text-primary-foreground whitespace-pre-wrap"
 92→              : "bg-secondary text-secondary-foreground prose-msg"
 93→          )}
 94→        >
 95→          {isUser ? (
 96→            message.content
 97→          ) : (
 98→            <Markdown remarkPlugins={[remarkGfm]}>{message.content}</Markdown>
 99→          )}
100→          <CopyButton text={message.content} />
101→        </div>
102→        <MessageTime
103→          timestamp={message.timestamp}
104→          className="mt-1 text-[10px] text-muted-foreground/60"
105→        />
106→      </div>
107→    </div>
108→  );
