  }, [messages, rawMessages, showRaw]);

  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
  const isActive = status === "connected" || status === "thinking";
  const isArchived = status === "done" || status === "disconnected" || status === "error";

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const trimmed = input.trim();
    if (!trimmed) return;

    if (isActive) {
      onSendMessage(trimmed);
    } else {
      onSpawnAgent(trimmed);
    }
    setInput("");
    setShowSlashMenu(false);
  }

  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
    const value = e.target.value;
    setInput(value);

    if (value.startsWith("/")) {
      setShowSlashMenu(true);
      setSlashQuery(value.slice(1));
      setSlashHighlight(0);
    } else {
      setShowSlashMenu(false);
      setSlashQuery("");
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (!showSlashMenu) return;
    const filtered = filterCommands(slashQuery);
    if (filtered.length === 0) return;

    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSlashHighlight((i) => (i + 1) % filtered.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
    } else if (e.key === "Enter") {
      e.preventDefault();
      handleCommandSelect(filtered[slashHighlight]);
    } else if (e.key === "Escape") {
      e.preventDefault();
      setShowSlashMenu(false);
    } else if (e.key === "Tab") {
      e.preventDefault();
      setInput(`/${filtered[slashHighlight].name} `);
      setShowSlashMenu(false);
    }
  }

  function handleCommandSelect(command: SlashCommand) {
    setShowSlashMenu(false);
    setSlashQuery("");
    setInput("");

    if (command.clientSide) {
      if (command.name === "clear") {
        onClearHistory?.();
      }
      return;
    }

    const commandText = `/${command.name}`;
    if (isActive) {
      onSendMessage(commandText);
    } else {
      onSpawnAgent(commandText);
    }
  }

  return (
    <div className="flex h-full flex-col">
      <StatusBar
        connected={connected}
        status={status}
        showRaw={showRaw}
        onToggleRaw={() => setShowRaw((v) => !v)}
        showTasks={showTasks}
        onToggleTasks={onToggleTasks}
        onToggleSidebar={onToggleSidebar}
      />
      <AgentSummary rawMessages={rawMessages} />

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
        {loading ? (
          <div className="flex h-full flex-col items-center justify-center gap-3">
            <div className="flex gap-1">
              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
            </div>
            <span className="text-xs text-muted-foreground">
              {connected ? "Loading messages..." : "Connecting..."}
            </span>
          </div>
        ) : showRaw ? (
          rawMessages.length === 0 ? (
            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
              No raw messages yet
            </div>
          ) : (
            <div className="space-y-1">
              {rawMessages.map((msg, i) => (
                <RawMessage key={i} message={msg} index={i} />
              ))}
            </div>
          )
        ) : (
          <>
            {messages.length === 0 && (
              <div className="flex h-full items-center justify-center">
                <div className="flex max-w-sm flex-col items-center gap-6 text-center">
                  <div className="flex size-12 items-center justify-center rounded-xl border bg-muted/50">
                    <Terminal className="size-6 text-muted-foreground" />
                  </div>
                  <div className="space-y-2">
                    <h2 className="text-base font-medium">Spawn an agent</h2>
                    <p className="text-sm text-muted-foreground">
                      Enter a prompt below to start a new Claude Code session. The agent runs in your terminal and streams results here in real time.
                    </p>
                  </div>
                  <div className="w-full space-y-2 text-left text-[13px]">
                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
                      <MessageSquare className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
                      <div>
                        <span className="font-medium">Chat</span>
                        <span className="text-muted-foreground"> — send follow-up messages to a running agent</span>
                      </div>
                    </div>
                    <div className="flex items-start gap-3 rounded-lg border px-3 py-2.5">
                      <ListTodo className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
                      <div>
                        <span className="font-medium">Tasks</span>
                        <span className="text-muted-foreground"> — create tasks and delegate them to agents</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
            {displayItems.map((item) => {
              if (item.kind === "condensed") {
                return <CondensedToolGroup key={item.id} group={item} />;
              }
              const msg = item.message;
              return msg.userQuestion ? (
                <UserQuestion
                  key={msg.id}
                  message={msg}
                  onRespond={onRespondToUserQuestion}
                />
              ) : msg.controlRequest ? (
                <ControlRequest
                  key={msg.id}
                  message={msg}
                  onRespond={onRespondToControl}
                />
              ) : (
                <Message key={msg.id} message={msg} />
              );
            })}
          </>
        )}
      </div>

      {isArchived && messages.length > 0 ? (
        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
          This session has ended
        </div>
      ) : (
        <form
          onSubmit={handleSubmit}
          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
        >
          {showSlashMenu && (
            <SlashCommandMenu
              query={slashQuery}
              highlightedIndex={slashHighlight}
              onSelect={handleCommandSelect}
              onHighlight={setSlashHighlight}
            />
          )}
          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
          />
          <Button type="submit" disabled={!connected || !input.trim()}>
            {isActive ? "Send" : "Spawn"}
          </Button>
        </form>
      )}
    </div>
  );
}

/** Badge color per Claude NDJSON message type. */
const TYPE_COLORS: Record<string, string> = {
  system: "text-yellow-500",
  assistant: "text-blue-400",
  result: "text-green-500",
  control_request: "text-orange-400",
  keep_alive: "text-muted-foreground",
};

function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
  const [expanded, setExpanded] = useState(false);
  const subtype = (message as { subtype?: string }).subtype;
  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";

  return (
    <div className="font-mono text-[11px] leading-relaxed">
      <button
        onClick={() => setExpanded((v) => !v)}
        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
      >
        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
        <span className={colorClass}>{typeLabel}</span>
        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
      </button>
      {expanded && (
        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
          {JSON.stringify(message, null, 2)}
        </pre>
      )}
    </div>
  );
}

"use client";

/**
 * Dashboard route (`/dashboard`).
 *
 * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
 * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
 * to `null`, which shows the spawn input. On spawn, the server responds
 * with `spawned` and the hook auto-selects the new agent.
 *
 * ## Loading states
 *
 * Two loading flags from the hook control the UI:
 * - `initialLoadDone` — false until the first `agent_list` arrives from
 *   the server. While false, the sidebar shows skeleton rows.
 * - `historyLoading` — true when the active agent's message history has
 *   not been fetched yet (lazy loading). The chat shows a "Loading
 *   messages..." indicator until the server responds.
 *
 * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 */

import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { useWebSocket } from "@/hooks/use-websocket";
import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
import { Chat } from "@/components/dashboard/chat";
import { TaskPanel } from "@/components/dashboard/kanban-board";
import type { TaskViewMode } from "@/components/dashboard/kanban-board";
import { Toaster } from "@/components/ui/sonner";
import { cn } from "@/lib/utils";

export default function DashboardPage() {
  const {
    connected,
    initialLoadDone,
    historyLoading,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
  } = useWebSocket();

  const [taskView, setTaskView] = useState<TaskViewMode | "hidden">("hidden");
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const showTasks = taskView !== "hidden";

  // Connection toast: skip initial load, only fire on transitions after first connect
  const hasConnectedRef = useRef(false);
  useEffect(() => {
    if (connected) {
      if (hasConnectedRef.current) {
        toast.success("Reconnected", { description: "WebSocket connection restored" });
      }
      hasConnectedRef.current = true;
    } else if (hasConnectedRef.current) {
      toast.error("Connection lost", { description: "Attempting to reconnect..." });
    }
  }, [connected]);

  useEffect(() => {
    document.title = "thos — dashboard";
  }, []);

  return (
    <>
    <div className="relative flex h-dvh overflow-hidden">
      {/* Sidebar backdrop (mobile only) */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar drawer */}
      <div
        className={cn(
          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
          sidebarOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <AgentSidebar
          agents={agents}
          agentOrder={agentOrder}
          activeAgentId={activeAgentId}
          loading={!initialLoadDone}
          onSelect={(id) => {
            setActiveAgentId(id);
            setSidebarOpen(false);
          }}
          onNewAgent={() => {
            setActiveAgentId(null);
            setSidebarOpen(false);
          }}
          onKill={killAgent}
          onDelete={deleteAgent}
          onRename={renameAgent}
          onClearHistory={clearHistory}
        />
      </div>

      {/* Main content: chat + optional task panel */}
      <div className="flex min-w-0 flex-1">
        {/* Chat — hidden only in board mode */}
        <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
          <Chat
            connected={connected}
            loading={!initialLoadDone || historyLoading}
            status={activeStatus}
            messages={activeMessages}
            rawMessages={activeRawMessages}
            onSendMessage={sendMessage}
            onSpawnAgent={spawnAgent}
            onRespondToControl={respondToControl}
            onRespondToUserQuestion={respondToUserQuestion}
            showTasks={showTasks}
            onToggleTasks={() => setTaskView((v) => v === "hidden" ? "list" : "hidden")}
            onToggleSidebar={() => setSidebarOpen((v) => !v)}
          />
        </div>

        {/* Task panel — list: right sidebar, board: full width */}
        {showTasks && (
          <div
            className={cn(
              "flex flex-col border-l bg-background",
              taskView === "list"
                ? "w-80 max-w-[calc(100vw-3rem)]"
                : "min-w-0 flex-1"
            )}
          >
            <TaskPanel
              tasks={tasks}
              mode={taskView as TaskViewMode}
              onModeChange={setTaskView}
              onCreateTask={createTask}
              onUpdateTask={updateTask}
              onDeleteTask={deleteTask}
              onDelegateTask={delegateTask}
              onSelectAgent={(agentId) => {
                setActiveAgentId(agentId);
              }}
              onClose={() => setTaskView("hidden")}
            />
          </div>
        )}
      </div>
    </div>
    <Toaster />
    </>
  );
}

